{
  "root_causes": [
    {
      "service": "ts-admin-basic-info-service",
      "fault_kind": "application_method_slow",
      "evidence": [
        {"kind": "trace", "sql": "SELECT span_name, attr_span_kind, count(*) c, round(avg(duration)/1e6,1) avg_ms, round(max(duration)/1e6,1) max_ms FROM abnormal_traces WHERE service_name='ts-admin-basic-info-service' AND span_name IN ('AdminBasicInfoController.getAllContacts','GET /api/v1/adminbasicservice/adminbasic/contacts') GROUP BY 1,2", "claim": "getAllContacts method and its contacts endpoint average about 1720 ms in the incident, versus about 8-10 ms normally."},
        {"kind": "trace", "sql": "SELECT c.span_name, c.attr_span_kind, round(avg(c.duration)/1e6,1) child_ms, round(avg(p.duration)/1e6,1) parent_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id = p.span_id AND c.trace_id = p.trace_id WHERE p.span_name='AdminBasicInfoController.getAllContacts' GROUP BY 1,2", "claim": "The outgoing GET to contacts takes about 5 ms while the enclosing method takes about 1718 ms, so the time is spent inside the method."},
        {"kind": "trace", "sql": "SELECT span_name, count(*) c, round(avg(duration)/1e6,1) ms FROM abnormal_traces WHERE service_name='ts-admin-basic-info-service' AND attr_span_kind='Server' GROUP BY 1 ORDER BY 1", "claim": "Other basic-info server endpoints (stations, prices, trains, configs) stay at about 5-8 ms during the incident."}
      ]
    }
  ],
  "propagation": [
    {"from": "ts-admin-basic-info-service", "to": "ts-ui-dashboard", "evidence": [{"kind": "trace", "sql": "SELECT service_name, span_name, count(*) c, round(avg(duration)/1e6,1) ms FROM abnormal_traces WHERE span_name='GET /api/v1/adminbasicservice/adminbasic/contacts' AND attr_span_kind='Server' GROUP BY 1,2", "claim": "The dashboard's own contacts endpoint inherits the roughly 1720 ms latency from ts-admin-basic-info-service."}]}
  ]
}
